use ark_bn254::{Fr,G1Affine};
use ark_ec::{AffineRepr,CurveGroup,VariableBaseMSM};
use ark_ff::PrimeField;
use ark_poly::DenseMultilinearExtension;
use ark_serialize::{CanonicalSerialize,CanonicalDeserialize};
use ark_std::{rand::rngs::OsRng};
use ark_crypto_primitives::sponge::{merlin::Transcript,CryptographicSponge};
use poly_commit::{hyrax::{HyraxPC,HyraxCommitment,HyraxProof,HyraxCommitmentState},PolynomialCommitment,LabeledPolynomial,LabeledCommitment};
use rayon::prelude::*;
use std::{collections::BTreeMap,fs,os::fd::AsRawFd,time::Instant};
use serde_json::{Value,json};
type PC=HyraxPC<G1Affine,DenseMultilinearExtension<Fr>>;
fn encode<T:CanonicalSerialize>(x:&T)->Vec<u8>{let mut b=Vec::new();x.serialize_compressed(&mut b).unwrap();b}
fn load<T:CanonicalDeserialize>(p:&str)->T{T::deserialize_compressed(&*fs::read(p).unwrap()).unwrap()}
fn tr()->Transcript{Transcript::new(b"native-hyrax-homomorphic-v2")}
fn u(x:&Value,k:&str)->usize{x[k].as_u64().unwrap() as usize}
fn groups(d:&Value)->BTreeMap<usize,Vec<usize>>{let mut g=BTreeMap::new();for (idx,t) in d["tensors"].as_array().unwrap().iter().enumerate(){assert_eq!(u(t,"index"),idx);let count=u(t,"element_count");let mut n=count.next_power_of_two().ilog2() as usize;if n%2!=0{n+=1}n=n.max(2);assert!(n<=30);g.entry(n).or_insert_with(Vec::new).push(idx);}g}
fn batch_challenges(meta:&[u8],cs:&[HyraxCommitment<G1Affine>],g:&BTreeMap<usize,Vec<usize>>)->(Vec<Fr>,BTreeMap<usize,Vec<Fr>>){let mut s=tr();s.absorb(&meta.to_vec());s.absorb(&encode(&cs.to_vec()));let a=s.squeeze_field_elements(cs.len());let points=g.keys().map(|n|(*n,s.squeeze_field_elements(*n))).collect();(a,points)}
fn aggregate_commit(cs:&[HyraxCommitment<G1Affine>],ids:&[usize],a:&[Fr])->HyraxCommitment<G1Affine>{let scalars:Vec<_>=ids.iter().map(|i|a[*i].into_bigint()).collect();let rows=(0..cs[ids[0]].row_coms.len()).into_par_iter().map(|row|{let bases:Vec<_>=ids.iter().map(|i|cs[*i].row_coms[row]).collect();<G1Affine as AffineRepr>::Group::msm_bigint(&bases,&scalars).into_affine()}).collect();HyraxCommitment{row_coms:rows}}
struct Source{ptr:*mut libc::c_void,len:usize,width:usize}
impl Source{
 fn new(p:&str,width:usize)->Self{let f=fs::File::open(p).unwrap();let len=f.metadata().unwrap().len() as usize;let ptr=unsafe{libc::mmap(std::ptr::null_mut(),len,libc::PROT_READ,libc::MAP_PRIVATE,f.as_raw_fd(),0)};assert_ne!(ptr,libc::MAP_FAILED);Self{ptr,len,width}}
 fn matrix(&self,d:&Value,idx:usize,n:usize)->Vec<Fr>{let t=&d["tensors"][idx];let rows=t["matrix_shape"][0].as_u64().unwrap() as usize;let cols=t["matrix_shape"][1].as_u64().unwrap() as usize;assert_eq!(rows*cols,u(t,"element_count"));let mut v=vec![Fr::from(0u64);1usize<<n];let bytes=unsafe{std::slice::from_raw_parts(self.ptr as *const u8,self.len)};let width=self.width;let mut off=0;let mut covered=0;
 for b in d["buckets"].as_array().unwrap(){let count=u(b,"entry_count");if u(b,"tensor_index")==idx{let rr=u(b,"physical_row_len");let cc=u(b,"physical_col_len");let ro=u(b,"row_offset");let co=u(b,"col_offset");let stride=u(b,"col_len");assert!(ro+rr<=rows&&co+cc<=cols);assert!((off+count)*self.width<=self.len);v[ro*cols..(ro+rr)*cols].par_chunks_mut(cols).enumerate().for_each(|(r,dst)|{for c in 0..cc{let at=(off+r*stride+c)*width;let x=if width==1{bytes[at] as i8 as i64}else{i16::from_le_bytes([bytes[at],bytes[at+1]]) as i64};dst[co+c]=if x<0{-Fr::from((-x) as u64)}else{Fr::from(x as u64)};}});covered+=rr*cc;}off+=count;}assert_eq!(covered,rows*cols);assert_eq!(off*self.width,self.len);v
 }
}
impl Drop for Source{fn drop(&mut self){unsafe{libc::munmap(self.ptr,self.len);}}}
fn verify(out:&str,negative:bool){let setup_t=Instant::now();let meta=fs::read(format!("{out}/description.json")).unwrap();let d:Value=serde_json::from_slice(&meta).unwrap();let g=groups(&d);let mut rng=OsRng;let mut keys=BTreeMap::new();for n in g.keys(){let pp=PC::setup(1,Some(*n),&mut rng).unwrap();let (_,vk)=PC::trim(&pp,1,1,None).unwrap();keys.insert(*n,vk);}let setup=setup_t.elapsed().as_secs_f64();let start=Instant::now();let cs:Vec<HyraxCommitment<G1Affine>>=load(&format!("{out}/commitments.bin"));assert_eq!(cs.len(),d["tensors"].as_array().unwrap().len());let (alphas,points)=batch_challenges(&meta,&cs,&g);let mut aggregation=0.;
 for (n,ids) in &g{let t=Instant::now();let c=aggregate_commit(&cs,ids,&alphas);aggregation+=t.elapsed().as_secs_f64();let lc=LabeledCommitment::new("batch".into(),c,Some(1));let proof:Vec<HyraxProof<G1Affine>>=load(&format!("{out}/group-{n}.proof"));assert_eq!(proof.len(),1);assert!(PC::check(&keys[n],[&lc],&points[n],[Fr::from(0u64)],&proof,&mut tr(),Some(&mut rng)).unwrap());}
 let timing=start.elapsed().as_secs_f64();
 if negative {let (n,ids)=g.iter().next().unwrap();let c=aggregate_commit(&cs,ids,&alphas);let lc=LabeledCommitment::new("batch".into(),c,Some(1));let proof:Vec<HyraxProof<G1Affine>>=load(&format!("{out}/group-{n}.proof"));let mut bad=proof.clone();bad[0].z[0]+=Fr::from(1u64);assert!(!PC::check(&keys[n],[&lc],&points[n],[Fr::from(0u64)],&bad,&mut tr(),Some(&mut rng)).unwrap());let mut wrong=points[n].clone();wrong[0]+=Fr::from(1u64);assert!(!PC::check(&keys[n],[&lc],&wrong,[Fr::from(0u64)],&proof,&mut tr(),Some(&mut rng)).unwrap());let mut altered=cs.clone();altered[ids[0]].row_coms[0]=(altered[ids[0]].row_coms[0].into_group()+G1Affine::generator()).into_affine();let (aa,pp)=batch_challenges(&meta,&altered,&g);let wrong_c=LabeledCommitment::new("batch".into(),aggregate_commit(&altered,ids,&aa),Some(1));assert!(!PC::check(&keys[n],[&wrong_c],&pp[n],[Fr::from(0u64)],&proof,&mut tr(),Some(&mut rng)).unwrap());eprintln!("PASS: corrupt proof, wrong point and changed constituent commitment rejected");}
 println!("{}",json!({"setup_seconds":setup,"verify_decode_io_seconds":timing,"commitment_aggregation_seconds_in_verify":aggregation,"verified_hidden_evaluation":true,"public_evaluation_checked":false,"groups":g.len()}));
}
fn main(){let a:Vec<String>=std::env::args().collect();if a[1]=="verify"{verify(&a[2],a.get(3).map(|x|x=="negative").unwrap_or(false));return}assert_eq!(a.len(),6,"INPUT WIDTH DESCRIPTION OUTPUT THREADS");let width:usize=a[2].parse().unwrap();assert!(width==1||width==2);let out=&a[4];let threads:usize=a[5].parse().unwrap();rayon::ThreadPoolBuilder::new().num_threads(threads).build_global().unwrap();fs::create_dir(out).unwrap();let meta=fs::read(&a[3]).unwrap();fs::write(format!("{out}/description.json"),&meta).unwrap();let d:Value=serde_json::from_slice(&meta).unwrap();let g=groups(&d);let source=Source::new(&a[1],width);assert_eq!(source.len,u(&d,"stream_entries")*width);let mut rng=OsRng;
 let t=Instant::now();let mut keys=BTreeMap::new();for n in g.keys(){let pp=PC::setup(1,Some(*n),&mut rng).unwrap();let (ck,_)=PC::trim(&pp,1,1,None).unwrap();keys.insert(*n,ck);}let setup=t.elapsed().as_secs_f64();let count=d["tensors"].as_array().unwrap().len();let mut cs:Vec<Option<HyraxCommitment<G1Affine>>>=vec![None;count];let mut blinds=vec![Vec::new();count];let mut commit=0.;let mut input=0.;let mut padded=0usize;
 for (n,ids) in &g{for idx in ids{let t=Instant::now();let values=source.matrix(&d,*idx,*n);input+=t.elapsed().as_secs_f64();padded+=values.len();let poly=LabeledPolynomial::new("matrix".into(),DenseMultilinearExtension::from_evaluations_vec(*n,values),None,None);let t=Instant::now();let (com,state)=PC::commit(&keys[n],[&poly],Some(&mut rng)).unwrap();commit+=t.elapsed().as_secs_f64();cs[*idx]=Some(com[0].commitment().clone());blinds[*idx]=state[0].batching_randomness().to_vec();eprintln!("committed matrix={} of={} num_vars={} commit_total={}",idx,count,n,commit);}}
 let cs:Vec<_>=cs.into_iter().map(Option::unwrap).collect();let commitment_bytes=encode(&cs);fs::write(format!("{out}/commitments.bin"),&commitment_bytes).unwrap();let t=Instant::now();let (alphas,points)=batch_challenges(&meta,&cs,&g);let mut aggregate=t.elapsed().as_secs_f64();let mut native_open=0.;let mut proof_bytes=0;
 for (n,ids) in &g{let t=Instant::now();let mut sum=vec![Fr::from(0u64);1usize<<n];let mut rand_sum=vec![Fr::from(0u64);1usize<<(n/2)];aggregate+=t.elapsed().as_secs_f64();for idx in ids{let t=Instant::now();let values=source.matrix(&d,*idx,*n);input+=t.elapsed().as_secs_f64();let t=Instant::now();sum.par_iter_mut().zip(values.par_iter()).for_each(|(x,y)|*x+=alphas[*idx]*y);for (x,y) in rand_sum.iter_mut().zip(&blinds[*idx]){*x+=alphas[*idx]*y;}aggregate+=t.elapsed().as_secs_f64();}
 let t=Instant::now();let c=aggregate_commit(&cs,ids,&alphas);let state=HyraxCommitmentState::batching_state(&sum,*n,rand_sum);aggregate+=t.elapsed().as_secs_f64();let poly=LabeledPolynomial::new("batch".into(),DenseMultilinearExtension::from_evaluations_vec(*n,sum),None,None);let lc=LabeledCommitment::new("batch".into(),c,Some(1));let t=Instant::now();let proof=PC::open(&keys[n],[&poly],[&lc],&points[n],&mut tr(),[&state],Some(&mut rng)).unwrap();let encoded=encode(&proof);native_open+=t.elapsed().as_secs_f64();proof_bytes+=encoded.len();fs::write(format!("{out}/group-{n}.proof"),encoded).unwrap();eprintln!("opened group={} matrices={} aggregate_total={} native_open_total={}",n,ids.len(),aggregate,native_open);}
 let mut usage:libc::rusage=unsafe{std::mem::zeroed()};unsafe{libc::getrusage(libc::RUSAGE_SELF,&mut usage);}
 let result=json!({"scope":"homomorphic size-grouped native Hyrax; hidden evaluation","threads":threads,"runs":1,"matrix_count":count,"group_count":g.len(),"group_matrix_counts":g.iter().map(|(n,v)|(n.to_string(),v.len())).collect::<BTreeMap<_,_>>(),"source_stream_entries":u(&d,"stream_entries"),"physical_entries":u(&d["layout"],"physical_entries"),"padded_entries":padded,"input_seconds":input,"setup_seconds":setup,"commit_seconds":commit,"aggregation_seconds_in_open":aggregate,"native_open_seconds":native_open,"open_seconds":aggregate+native_open,"prover_seconds":commit+aggregate+native_open,"proof_bytes":proof_bytes,"commitment_bytes":commitment_bytes.len(),"peak_rss_kib":usage.ru_maxrss,"public_evaluation_checked":false});fs::write(format!("{out}/summary.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{result}");}

